/* 全部控件创建完成后统一注册；每次新建屏幕只调用一次。 */
void aido_event_init_menu(aidogui_ui_t * ui)
{
    aido_flow_observe(aidogui_ui.menu.root);
    aido_flow_observe(aidogui_ui.menu.TopRule);
    aido_flow_observe(aidogui_ui.menu.BrandMarkRing);
    aido_flow_observe(aidogui_ui.menu.BrandMarkCore);
    aido_flow_observe(aidogui_ui.menu.StatusBattery);
    aido_flow_observe(aidogui_ui.menu.StatusBluetooth);
    aido_flow_observe(aidogui_ui.menu.StatusWifi);
    aido_flow_observe(aidogui_ui.menu.MenuTitle);
    aido_flow_observe(aidogui_ui.menu.MenuSensorIcon);
    aido_flow_observe(aidogui_ui.menu.MenuSensorText);
    aido_flow_observe(aidogui_ui.menu.SensorHit);
    aido_flow_observe(aidogui_ui.menu.MenuSensor);
    aido_flow_observe(aidogui_ui.menu.MenuNetworkIcon);
    aido_flow_observe(aidogui_ui.menu.MenuNetworkText);
    aido_flow_observe(aidogui_ui.menu.NetworkHit);
    aido_flow_observe(aidogui_ui.menu.MenuNetwork);
    aido_flow_observe(aidogui_ui.menu.MenuBleIcon);
    aido_flow_observe(aidogui_ui.menu.MenuBleText);
    aido_flow_observe(aidogui_ui.menu.BleHit);
    aido_flow_observe(aidogui_ui.menu.MenuBle);
    aido_flow_observe(aidogui_ui.menu.MenuAudioIcon);
    aido_flow_observe(aidogui_ui.menu.MenuAudioText);
    aido_flow_observe(aidogui_ui.menu.AudioHit);
    aido_flow_observe(aidogui_ui.menu.MenuAudio);
    aido_flow_observe(aidogui_ui.menu.MenuDisplayIcon);
    aido_flow_observe(aidogui_ui.menu.MenuDisplayText);
    aido_flow_observe(aidogui_ui.menu.DisplayHit);
    aido_flow_observe(aidogui_ui.menu.MenuDisplay);
    aido_flow_observe(aidogui_ui.menu.MenuSystemIcon);
    aido_flow_observe(aidogui_ui.menu.MenuSystemText);
    aido_flow_observe(aidogui_ui.menu.SystemHit);
    aido_flow_observe(aidogui_ui.menu.MenuSystem);
    aido_flow_observe(aidogui_ui.menu.MenuStage);
    lv_obj_remove_event_cb(ui->menu.MenuSensor, MenuSensor_event_handler);
    lv_obj_add_event_cb(ui->menu.MenuSensor, MenuSensor_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.SensorHit, SensorHit_event_handler);
    lv_obj_add_event_cb(ui->menu.SensorHit, SensorHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.MenuNetwork, MenuNetwork_event_handler);
    lv_obj_add_event_cb(ui->menu.MenuNetwork, MenuNetwork_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.NetworkHit, NetworkHit_event_handler);
    lv_obj_add_event_cb(ui->menu.NetworkHit, NetworkHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.MenuBle, MenuBle_event_handler);
    lv_obj_add_event_cb(ui->menu.MenuBle, MenuBle_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.BleHit, BleHit_event_handler);
    lv_obj_add_event_cb(ui->menu.BleHit, BleHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.MenuAudio, MenuAudio_event_handler);
    lv_obj_add_event_cb(ui->menu.MenuAudio, MenuAudio_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.AudioHit, AudioHit_event_handler);
    lv_obj_add_event_cb(ui->menu.AudioHit, AudioHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.MenuDisplay, MenuDisplay_event_handler);
    lv_obj_add_event_cb(ui->menu.MenuDisplay, MenuDisplay_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.DisplayHit, DisplayHit_event_handler);
    lv_obj_add_event_cb(ui->menu.DisplayHit, DisplayHit_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.MenuSystem, MenuSystem_event_handler);
    lv_obj_add_event_cb(ui->menu.MenuSystem, MenuSystem_event_handler, LV_EVENT_ALL, ui);
    lv_obj_remove_event_cb(ui->menu.SystemHit, SystemHit_event_handler);
    lv_obj_add_event_cb(ui->menu.SystemHit, SystemHit_event_handler, LV_EVENT_ALL, ui);
}

